/** Offline fixture author/verifier only. Never embedded in a client save or gameplay JAR. */
public final class ExpandedContainerField extends JavaPlugin {
 public ExpandedContainerField(JavaPluginInit init){super(init);}
 record Station(String role,String family,String color,int x,int z){Vector3d pad(){return new Vector3d(x,64,z-.5);}Vector3d npc(){return new Vector3d(x,64,z+7.5);}}
 static final Set<String> OLD=Set.of("Kweebec_Sapling_HyThiefWitness","Feran_Civilian_HyThiefWitness","Kweebec_Razorleaf","Feran_Sharptooth");
 World w;Store<EntityStore>s;List<Station>stations=new ArrayList<>();List<String>evidence=new ArrayList<>();Map<String,Ref<EntityStore>>roles=new HashMap<>();String mode=System.getProperty("field.mode","verify");
 Ref<EntityStore>actor;Station selected;int ticks;float healthBefore;boolean combat;
 void out(String text){evidence.add(text);System.out.println("EXPANDED_FIELD "+text);}
 static void require(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
 protected void start(){Universe.get().getUniverseReady().thenRun(()->{w=Universe.get().getDefaultWorld();var loads=new ArrayList<CompletableFuture<?>>();for(int x=-2;x<=1;x++)for(int z=-1;z<=3;z++)for(int y=1;y<=2;y++)loads.add(w.getChunkStore().getChunkSectionReferenceAsync(x,y,z,GetChunkFlags.SET_TICKING));CompletableFuture.allOf(loads.toArray(CompletableFuture[]::new)).thenRun(()->w.execute(()->{try{init();}catch(Throwable e){fail(e);}}));});}
 void index(){roles.clear();s.forEachChunk(NPCEntity.getComponentType(),(c,b)->{for(int i=0;i<c.size();i++){var r=c.getReferenceTo(i);String name=s.getComponent(r,NPCEntity.getComponentType()).getRoleName();require(roles.put(name,r)==null,"duplicate NPC role "+name);}});}
 Set<String>enabled(){var names=new HashSet<String>(Set.of("Kweebec_Sapling_HyThiefWitness","Feran_Civilian_HyThiefWitness"));for(var station:stations)names.add(station.role());return names;}
 void init()throws Exception{s=w.getEntityStore().getStore();for(var value:JsonParser.parseString(Files.readString(Path.of("passive-stations.json"))).getAsJsonArray()){var a=value.getAsJsonObject();stations.add(new Station(a.get("Role").getAsString(),a.get("Family").getAsString(),a.get("Color").getAsString(),a.get("X").getAsInt(),a.get("Z").getAsInt()));}index();for(int z:new int[]{-6,-2,2,6})ensureChest(0,z);
  if(mode.equals("author")){require(!w.getWorldConfig().isTicking(),"author must run paused");require(roles.keySet().equals(OLD),"original NPC set changed");String before=snapshotOriginal();author();index();require(snapshotOriginal().equals(before),"original area changed during authoring");Files.writeString(Path.of("original-area.sha256"),before);out("ORIGINAL_AREA_PRESERVED SHA256="+before);finish("AUTHOR_PASS");}
  else if(mode.equals("verify")){require(!w.getWorldConfig().isTicking(),"geometry verification must run paused");require(snapshotOriginal().equals(Files.readString(Path.of("original-area.sha256"))),"persisted original area changed");verify();finish("VERIFY_PASS");}
  else if(mode.startsWith("response-")){selected=stations.stream().filter(a->a.role().equals(mode.substring(9))).findFirst().orElseThrow();require(w.getWorldConfig().isTicking(),"combat proof requires native ticks");actor=spawn("Test_Dummy_Stationary",selected.pad());var movement=new MovementStatesComponent();movement.setMovementStates(new com.hypixel.hytale.protocol.MovementStates());s.putComponent(actor,MovementStatesComponent.getComponentType(),movement);out("SURROGATE_ATTITUDE_SETUP Role="+selected.role());s.getComponent(roles.get(selected.role()),WorldSupport.getComponentType()).overrideAttitude(actor,Attitude.FRIENDLY,600);healthBefore=health();schedule();}
  else throw new IllegalArgumentException(mode);
 }
 Ref<EntityStore>spawn(String role,Vector3d position){var pair=NPCPlugin.get().spawnNPC(s,role,null,position,Rotation3f.ZERO);require(pair!=null,"spawn failed "+role);return pair.first();}
 void label(String text,double x,double y,double z){var h=EntityStore.REGISTRY.newHolder();h.addComponent(TransformComponent.getComponentType(),new TransformComponent(new Vector3d(x,y,z),new Rotation3f()));h.addComponent(Nameplate.getComponentType(),new Nameplate(text));h.addComponent(ModelComponent.getComponentType(),new ModelComponent(com.hypixel.hytale.server.core.asset.type.model.config.Model.createStaticScaledModel(com.hypixel.hytale.server.core.asset.type.model.config.ModelAsset.getAssetMap().getAsset("Arrow_Iron"),.01f)));h.addComponent(com.hypixel.hytale.server.core.entity.Frozen.getComponentType(),com.hypixel.hytale.server.core.entity.Frozen.get());h.addComponent(com.hypixel.hytale.server.core.entity.UUIDComponent.getComponentType(),com.hypixel.hytale.server.core.entity.UUIDComponent.randomUUID());s.addEntity(h,AddReason.SPAWN);}
 void author(){
  for(int x=-1;x<=1;x++)for(int z=27;z<=82;z++)NativeFieldBlocks.set(w,x,63,z,"Cloth_Block_Wool_Gray_Light");
  for(int x=-37;x<=37;x++)for(int z=40;z<=42;z++)NativeFieldBlocks.set(w,x,63,z,"Cloth_Block_Wool_Gray_Light");
  for(int x=-19;x<=19;x++)for(int z=80;z<=82;z++)NativeFieldBlocks.set(w,x,63,z,"Cloth_Block_Wool_Gray_Light");
  label("PASSIVE WITNESSES - FOLLOW GRAY PATH / PURPLE TRORK STRAIGHT",0,67,28.5);
  label("ORANGE GOBLIN <  |  PURPLE TRORK  |  > CYAN OUTLANDER",0,67,41.5);
  label("WHITE SKELETON <  |  > BLACK ZOMBIE",0,67,81.5);
  for(var a:stations){
   for(int x=a.x()-4;x<=a.x()+3;x++)for(int z=a.z()-3;z<=a.z()+11;z++){NativeFieldBlocks.set(w,x,63,z,"Rock_Stone_Cobble");for(int y=64;y<=69;y++)NativeFieldBlocks.set(w,x,y,z,"Empty");}
   for(int x=a.x()-1;x<=a.x()+1;x++)for(int z=a.z()-6;z<a.z()-2;z++)NativeFieldBlocks.set(w,x,63,z,"Cloth_Block_Wool_"+a.color());
   for(int x=a.x()-3;x<=a.x()+2;x++)for(int z=a.z()-2;z<=a.z()+1;z++)NativeFieldBlocks.set(w,x,63,z,"Cloth_Block_Wool_"+a.color());
   NativeFieldBlocks.set(w,a.x(),64,a.z(),"Furniture_Kweebec_Chest_Large");var cs=w.getChunkStore();var section=cs.getChunkSectionReferenceAtBlock(a.x(),64,a.z());var components=cs.getStore().getComponent(section,BlockComponentSection.getComponentType());var ref=BlockEntity.ensureBlockEntity(cs.getStore(),section,components,a.x(),64,a.z(),NativeFieldBlocks.type(w,a.x(),64,a.z()),0);var inv=cs.getStore().getComponent(ref,ItemContainerBlock.getComponentType());if(inv.getItemContainer()==null)inv.setItemContainer(new SimpleItemContainer(inv.getCapacity()));inv.getItemContainer().setItemStackForSlot((short)0,new ItemStack("Ingredient_Bar_Copper",16));inv.getItemContainer().setItemStackForSlot((short)1,new ItemStack("Ingredient_Bar_Iron",8));cs.getStore().putComponent(ref,OwnershipProofData.getComponentType(),new OwnershipProofData(true,"FACTION",a.family()));components.markBlockNeedsSaving(com.hypixel.hytale.math.util.ChunkUtil.indexBlock(a.x(),64,a.z()));components.markNeedsSaving();
   var npc=spawn(a.role(),a.npc());s.putComponent(npc,Nameplate.getComponentType(),new Nameplate("PASSIVE - "+a.role()));
   label(a.color().toUpperCase()+" - "+a.role()+" / FACTION "+a.family(),a.x(),68,a.z()+1.5);label("OPEN / DEPOSIT SAFE - STAND ON CENTER SEAM - REMOVE = CAUGHT",a.x(),66.5,a.z()+.5);
   out("STATION_AUTHORED Role="+a.role()+" Color="+a.color()+" Chest="+a.x()+",64,"+a.z()+" NPC="+a.npc()+" Ownership=FACTION:"+a.family());
  }
 }
 ItemContainer chest(Station a){var c=BlockModule.getComponent(ItemContainerBlock.getComponentType(),w,a.x(),64,a.z());require(c!=null&&c.getItemContainer()!=null,"missing chest "+a.role());return c.getItemContainer();}
 Ref<ChunkStore>ensureChest(int x,int z){var cs=w.getChunkStore();var section=cs.getChunkSectionReferenceAtBlock(x,64,z);var components=cs.getStore().getComponent(section,BlockComponentSection.getComponentType());return BlockEntity.ensureBlockEntity(cs.getStore(),section,components,x,64,z,NativeFieldBlocks.type(w,x,64,z),NativeFieldBlocks.section(w,x,64,z).getRotationIndex(x,64,z));}
 OwnershipProofData ownership(Station a){var r=BlockModule.getBlockEntity(w,a.x(),64,a.z());return w.getChunkStore().getStore().getComponent(r,OwnershipProofData.getComponentType());}
 Ref<EntityStore>geometryActor(){var k=roles.get("Kweebec_Sapling_HyThiefWitness");var h=EntityStore.REGISTRY.newHolder();h.addComponent(TransformComponent.getComponentType(),new TransformComponent(new Vector3d(0,64,0),new Rotation3f()));h.addComponent(com.hypixel.hytale.server.core.modules.physics.component.Velocity.getComponentType(),new com.hypixel.hytale.server.core.modules.physics.component.Velocity());h.addComponent(ModelComponent.getComponentType(),new ModelComponent(s.getComponent(k,ModelComponent.getComponentType()).getModel()));var box=s.getComponent(k,BoundingBox.getComponentType());if(box!=null)h.addComponent(BoundingBox.getComponentType(),(BoundingBox)box.clone());var movement=new MovementStatesComponent();movement.setMovementStates(new com.hypixel.hytale.protocol.MovementStates());h.addComponent(MovementStatesComponent.getComponentType(),movement);return s.addEntity(h,AddReason.SPAWN);}
 void verify()throws Exception{
  require(roles.size()==9&&roles.keySet().containsAll(OLD),"expected original four plus five NPCs");int chests=0;
  for(int x=-64;x<64;x++)for(int z=-32;z<128;z++)for(int y=64;y<=68;y++)if(NativeFieldBlocks.type(w,x,y,z).getId().contains("Chest")&&NativeFieldBlocks.filler(w,x,y,z)==0)chests++;
  require(chests==9,"expected exactly nine native chests: "+chests);actor=geometryActor();
  for(var a:stations){ensureChest(a.x(),a.z());var witness=roles.get(a.role());require(witness!=null,"missing representative");require(s.getComponent(witness,WorldSupport.getComponentType()).getDefaultPlayerAttitude()==Attitude.FRIENDLY,"passive setting missing");require(s.getComponent(witness,CombatSupport.getComponentType())!=null&&s.getComponent(witness,NPCEntity.getComponentType()).getRole().getRootInstruction()!=null,"native AI missing");require(s.getComponent(witness,com.hypixel.hytale.server.core.entity.Frozen.getComponentType())==null,"NPC frozen");var position=s.getComponent(witness,TransformComponent.getComponentType()).getPosition();require(position.distance(a.npc())<.001,"saved NPC moved");var data=ownership(a);require(data!=null&&data.owned()&&data.scope().equals("FACTION")&&data.faction().equals(a.family()),"ownership lost");require(ContainerOwnershipPolicy.rejection(data,witness,s)==null,"native group mismatch");var c=chest(a);require(c.getItemStack((short)0).getQuantity()==16&&c.getItemStack((short)1).getQuantity()==8,"loot lost");
   s.getComponent(actor,TransformComponent.getComponentType()).setPosition(a.pad());var visible=ContainerVisualWitness.evaluate(witness,actor,a.pad(),false,s);require(visible.seen()&&Math.abs(visible.distance()-8)<.001,"initial geometry "+visible.diagnostic());double nearest=Double.POSITIVE_INFINITY;for(var r:roles.values())if(!r.equals(witness)){double distance=s.getComponent(r,TransformComponent.getComponentType()).getPosition().distance(a.pad());nearest=Math.min(nearest,distance);require(distance>20,"cross-witnessing "+a.role());}
   var captured=ContainerVisualWitness.capture(actor,s,data,enabled(),this::out);require(captured.stream().filter(ContainerVisualWitness.Evidence::seen).count()==1&&captured.stream().filter(ContainerVisualWitness.Evidence::seen).allMatch(e->e.witness().equals(witness)),"wrong personal witness");
   require(!ContainerVisualWitness.evaluate(witness,actor,a.pad(),true,s).seen(),"crouched 8 range");
   for(int x=a.x()-2;x<=a.x()+1;x++)for(int y=64;y<=68;y++)NativeFieldBlocks.set(w,x,y,a.z()+4,"Rock_Stone_Cobble");var blocked=ContainerVisualWitness.evaluate(witness,actor,a.pad(),false,s);require(blocked.sector()&&!blocked.los()&&!blocked.seen(),"blocked LOS failed");for(int x=a.x()-2;x<=a.x()+1;x++)for(int y=64;y<=68;y++)NativeFieldBlocks.set(w,x,y,a.z()+4,"Empty");require(ContainerVisualWitness.evaluate(witness,actor,a.pad(),false,s).seen(),"cleared LOS failed");safeActions(a,c);
   out("STATION_VALID Role="+a.role()+" Color="+a.color()+" Ownership=FACTION:"+a.family()+" Passive=FRIENDLY Distance="+visible.distance()+" HeadYaw="+visible.headYaw()+" FOV="+visible.sector()+" LOS="+visible.los()+" NearestOtherNPC="+nearest+" BlockedLOS=UNSEEN NativeChest=true Peers=0");
  }
  for(int z:new int[]{-6,-2,2,6})for(var a:stations)require(s.getComponent(roles.get(a.role()),TransformComponent.getComponentType()).getPosition().distance(new Vector3d(0,64,z-.5))>20,"new NPC inside old field sight");
  for(var id:Universe.get().getPlayerStorage().getPlayers()){var h=Universe.get().getPlayerStorage().load(id).join();require(h.getComponent(TransformComponent.getComponentType()).getPosition().distance(new Vector3d(0,64.1,10.5))<.001,"spawn changed");var blocks=h.getComponent(InventoryComponent.Hotbar.getComponentType()).getInventory().getItemStack((short)0);require(blocks.getItemId().equals("Rock_Stone_Cobble")&&blocks.getQuantity()==64,"starting blocks lost");}
  s.removeEntity(actor,RemoveReason.REMOVE);require(snapshotOriginal().equals(Files.readString(Path.of("original-area.sha256"))),"original field changed during validation");out("ALL_STATIONS_VALID NativeChests=9 NPCs=9 OldAreaPreserved=true NormalPerception=15/4 ContainerWitness=20/6 SpawnUnchanged=true StartingBlocks=64");
 }
 void safeActions(Station a,ItemContainer c){var incoming=new SimpleItemContainer((short)4);incoming.setItemStackForSlot((short)0,new ItemStack("Ingredient_Fibre",3));var probe=new ContainerRemovalProbe(c,r->{throw new IllegalStateException("safe action counted as theft");},r->{});var one=c.registerChangeEvent(e->probe.source(e.transaction()));var two=incoming.registerChangeEvent(e->probe.receipt(e.transaction()));try{var section=w.getChunkStore().getChunkSectionReferenceAtBlock(a.x(),64,a.z());var base=NativeFieldBlocks.type(w,a.x(),64,a.z());require("Open_Container".equals(base.getInteractions().get(com.hypixel.hytale.protocol.InteractionType.Use)),"native chest Use replaced");for(String state:List.of("OpenWindow","CloseWindow"))com.hypixel.hytale.server.core.universe.world.chunk.BlockOperations.setBlockInteractionState(w.getChunkStore(),section,a.x(),64,a.z(),base,state,false);incoming.moveItemStackFromSlotToSlot((short)0,3,c,(short)5);c.moveItemStackFromSlotToSlot((short)5,3,c,(short)6);require(probe.finish()==0,"non-theft transaction");}finally{one.unregister();two.unregister();}out("SAFE_ACTIONS_PASS Role="+a.role()+" NativeOpenClose=true Deposit=true Rearrange=true FalseThefts=0");}
 String snapshotOriginal()throws Exception{var text=new StringBuilder();for(int x=-26;x<=26;x++)for(int z=-16;z<=26;z++)for(int y=63;y<=70;y++){var section=NativeFieldBlocks.section(w,x,y,z);text.append(x).append(',').append(y).append(',').append(z).append(':').append(NativeFieldBlocks.type(w,x,y,z).getId()).append(':').append(section.getFiller(x,y,z)).append(':').append(section.getRotationIndex(x,y,z)).append(';');}
  for(var name:new TreeSet<>(OLD)){var r=roles.get(name);require(r!=null,"original NPC absent");text.append(name).append(s.getComponent(r,TransformComponent.getComponentType()).getPosition()).append(s.getComponent(r,HeadRotation.getComponentType()).getRotation()).append(s.getComponent(r,StateSupport.getComponentType()).getStateName());}
  for(int z:new int[]{-6,-2,2,6}){var r=BlockModule.getBlockEntity(w,0,64,z);var data=w.getChunkStore().getStore().getComponent(r,OwnershipProofData.getComponentType());var inv=BlockModule.getComponent(ItemContainerBlock.getComponentType(),w,0,64,z).getItemContainer();text.append(data.owned()).append(data.scope()).append(data.faction());for(short n=0;n<inv.getCapacity();n++){var stack=inv.getItemStack(n);text.append(stack==null||stack.isEmpty()?"EMPTY":stack.getItemId()+":"+stack.getQuantity());}}
  var labels=new ArrayList<String>();s.forEachChunk(Nameplate.getComponentType(),(c,b)->{for(int i=0;i<c.size();i++){var r=c.getReferenceTo(i);var t=s.getComponent(r,TransformComponent.getComponentType());if(t!=null&&t.getPosition().x>=-26&&t.getPosition().x<=26&&t.getPosition().z>=-16&&t.getPosition().z<=26)labels.add(s.getComponent(r,Nameplate.getComponentType()).getText()+t.getPosition());}});Collections.sort(labels);for(var label:labels)text.append(label);return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.toString().getBytes(StandardCharsets.UTF_8)));
 }
 float health(){return s.getComponent(actor,EntityStatMap.getComponentType()).get(DefaultEntityStatTypes.getHealth()).get();}
 void schedule(){w.scheduleAfter(()->w.execute(()->{try{tick();}catch(Throwable e){fail(e);}}),250,TimeUnit.MILLISECONDS);}
 void tick()throws Exception{ticks++;var witness=roles.get(selected.role());var state=s.getComponent(witness,StateSupport.getComponentType()).getStateName();if(ticks<=16)require(!state.startsWith("Combat")&&!state.startsWith("Chase"),"not passive before removal "+state);
  if(ticks==16){s.getComponent(witness,TransformComponent.getComponentType()).setPosition(selected.npc());s.getComponent(witness,HeadRotation.getComponentType()).getRotation().setYaw(0);out("PASSIVE_WINDOW_PASS Role="+selected.role()+" State="+state);var c=chest(selected);var data=ownership(selected);var confirmed=new ArrayList<ContainerVisualWitness.Evidence>();var snaps=new IdentityHashMap<ContainerRemovalProbe.Removal,List<ContainerVisualWitness.Evidence>>();var receipts=new SimpleItemContainer((short)4);var probe=new ContainerRemovalProbe(c,r->confirmed.addAll(snaps.getOrDefault(r,List.of())),r->snaps.put(r,ContainerVisualWitness.capture(actor,s,data,enabled(),this::out)));var one=c.registerChangeEvent(e->probe.source(e.transaction()));var two=receipts.registerChangeEvent(e->probe.receipt(e.transaction()));try{c.moveItemStackFromSlotToSlot((short)0,1,receipts,(short)0);require(probe.finish()==1,"withdraw attribution");}finally{one.unregister();two.unregister();}var messages=new ArrayList<com.hypixel.hytale.server.core.Message>();ContainerCaughtNotification.notifyWitnessed(confirmed,messages::add);require(messages.size()==1,"caught count");require(HyThiefPersonalWitnessAlert.deliver(data,actor,confirmed,s,this::out)==1,"personal native handoff");out("FACTION_WITHDRAWAL_PASS Role="+selected.role()+" Notifications=1 PersonalDeliveries=1");}
  if(ticks>16){boolean target=actor.equals(s.getComponent(witness,MarkedEntitySupport.getComponentType()).getMarkedEntityRef("LockedTarget"));if(target&&(state.startsWith("Combat")||state.startsWith("Chase")))combat=true;}
  if(ticks>=96){require(combat&&health()<healthBefore,"native combat/damage absent");out("NATIVE_RESPONSE_PASS Role="+selected.role()+" TargetOffender=true Damage="+(healthBefore-health())+" CustomBroadcast=false");finish("RESPONSE_PASS");return;}schedule();
 }
 void finish(String status){out(status);try{Files.write(Path.of("field-evidence.txt"),evidence);}catch(Exception e){throw new RuntimeException(e);}CompletableFuture.runAsync(()->com.hypixel.hytale.server.core.HytaleServer.get().shutdownServer());}
 void fail(Throwable e){out("FAILED "+e);e.printStackTrace();finish("FAILED");}
}
